import Foundation

/// Localised text. Keys are the English text, which is the base language: a missing
/// translation shows English. Translations live in `Resources/<language>.lproj/
/// Localizable.strings` (ja, zh-Hans, zh-Hant), generated by `Localization/build-strings.py`.
func L(_ key: String) -> String {
    NSLocalizedString(key, comment: "")
}

/// Localised format string filled with `args`. Keys use numbered placeholders (`%1$@`,
/// `%2$ld`) wherever a translation may need the arguments in another order.
func L(_ key: String, _ args: CVarArg...) -> String {
    String(format: L(key), locale: Locale.current, arguments: args)
}
